use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:2.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_volume_zscore",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,v:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{let p=x[0]as usize;Ok(Box::new(I{p,v:RingVec::new(p)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{self.v.push(t.qty);if self.v.len()!=self.p{return None}let m=self.v.iter().sum::<f64>()/self.p as f64;let s=(self.v.iter().map(|x|(x-m).powi(2)).sum::<f64>()/self.p as f64).sqrt();Some(if s==0.{0.}else{(t.qty-m)/s})}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(q:f64)->Trade{Trade{price:1.,qty:q,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn z(){let mut i=create(&[2.]).unwrap();i.on_trade(&t(1.));assert!(i.on_trade(&t(3.)).unwrap()>0.);}}
